/**
 * Intelligent stemmer and dictionary normalizer
 * Strips French accents, normalizes ligatures (œ, æ), and handles elisions/clitics.
 */
window.normalizeFrenchWord = function(rawWord) {
  if (!rawWord) return "";
  let clean = rawWord.trim().toLowerCase().replace(/[\u2018\u2019\u02bc]/g, "'");

  // Normalize ligatures
  clean = clean.replace(/œ/g, "oe").replace(/æ/g, "ae");

  // Strip trailing and surrounding punctuation except apostrophe and hyphens
  clean = clean.replace(/[.,\/#!$%\^&\*;:{}=\_~`()?"«»]/g, '');

  // 1. If clean directly exists in FRENCH_VOCAB_DB (e.g. "jusqu'à", "c'est", "d'accord", "aujourd'hui", "à", "où", "sûr"), preserve it!
  if (window.FRENCH_VOCAB_DB && (window.FRENCH_VOCAB_DB[clean] || window.FRENCH_VOCAB_DB[clean.replace(/'/g, '')])) {
    return clean;
  }

  // 2. Strip leading elisions for regular nouns/verbs: l'oiseau -> oiseau, d'eau -> eau, j'aime -> aime, m'appelle -> appelle, s'amuse -> amuse
  clean = clean.replace(/^(jusqu'|lorsqu'|puisqu'|l'|d'|qu'|s'|c'|m'|t'|n'|j')/i, '');

  // 3. Strip trailing clitics if hyphenated (e.g. donne-moi -> donne, dit-il -> dit, est-ce -> est)
  clean = clean.replace(/-(t-il|t-elle|t-on|moi|toi|lui|le|la|les|nous|vous|en|y|il|elle|on|ils|elles|je|tu|ce|la|ci)$/i, '');

  // 4. Strip remaining apostrophes or hyphens if any
  clean = clean.replace(/['\-]/g, '');

  return clean;
};

window.stripAccents = function(str) {
  if (!str) return "";
  return str
    .replace(/œ/g, "oe")
    .replace(/Œ/g, "oe")
    .replace(/æ/g, "ae")
    .replace(/Æ/g, "ae")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");
};

/**
 * Look up word in dictionary with robust grammatical heuristics
 * (verb conjugations, passé simple, plurals, feminine endings, adverbs)
 */
window.lookupFrenchWord = function(rawWord) {
  if (!rawWord) return null;
  const rawTrim = rawWord.trim().replace(/[\u2018\u2019\u02bc]/g, "'");
  const lower = rawTrim.toLowerCase().replace(/œ/g, "oe").replace(/æ/g, "ae");
  const strippedPunct = lower.replace(/[.,\/#!$%\^&\*;:{}=\_~`()?"«»]/g, '');

  // 1. Direct match with exact accents & apostrophe intact (e.g. "jusqu'à", "c'est", "à", "où", "sûr", "dès", "dû")
  if (window.FRENCH_VOCAB_DB[strippedPunct]) {
    return {
      word: rawWord,
      cleanWord: strippedPunct,
      ...window.FRENCH_VOCAB_DB[strippedPunct]
    };
  }

  // 2. Direct match without apostrophe in key (e.g. "chef-d'oeuvre", "aujourd'hui")
  const normApos = strippedPunct.replace(/'/g, '');
  if (window.FRENCH_VOCAB_DB[normApos]) {
    return {
      word: rawWord,
      cleanWord: normApos,
      ...window.FRENCH_VOCAB_DB[normApos]
    };
  }

  // 3. Normalization through stemmer
  const clean = window.normalizeFrenchWord(rawWord);
  if (!clean) return null;

  // Direct match on clean
  if (window.FRENCH_VOCAB_DB[clean]) {
    return {
      word: rawWord,
      cleanWord: clean,
      ...window.FRENCH_VOCAB_DB[clean]
    };
  }

  // 4. Accent-stripped match (e.g. "étais" -> "etais", "vécu" -> "vecu", "forêt" -> "foret")
  const noAcc = window.stripAccents(clean);
  if (window.FRENCH_VOCAB_DB[noAcc] && clean.length > 1) {
    return {
      word: rawWord,
      cleanWord: clean,
      ...window.FRENCH_VOCAB_DB[noAcc]
    };
  }

  // 5. Singularize plural 'es', 's', 'x', or '-aux' -> '-al'
  if (clean.endsWith('aux') && clean.length > 4) {
    const singAl = noAcc.slice(0, -3) + 'al';
    if (window.FRENCH_VOCAB_DB[singAl]) {
      const match = window.FRENCH_VOCAB_DB[singAl];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en + " (plural)",
        pos: match.pos,
        ipa: match.ipa,
        gender: match.gender
      };
    }
  }

  if (clean.endsWith('es') && clean.length > 3) {
    const singMasc = noAcc.slice(0, -2);
    if (window.FRENCH_VOCAB_DB[singMasc]) {
      const match = window.FRENCH_VOCAB_DB[singMasc];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en + " (fem. pl.)",
        pos: match.pos,
        ipa: match.ipa,
        gender: "f"
      };
    }
  }

  if (clean.endsWith('s') && clean.length > 2) {
    const singular = window.stripAccents(clean.slice(0, -1));
    if (window.FRENCH_VOCAB_DB[singular]) {
      const match = window.FRENCH_VOCAB_DB[singular];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en + " (plural)",
        pos: match.pos,
        ipa: match.ipa,
        gender: match.gender
      };
    }
  }

  if (clean.endsWith('x') && clean.length > 3) {
    const singular = window.stripAccents(clean.slice(0, -1));
    if (window.FRENCH_VOCAB_DB[singular]) {
      const match = window.FRENCH_VOCAB_DB[singular];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en,
        pos: match.pos,
        ipa: match.ipa,
        gender: match.gender
      };
    }
  }

  // 6. Feminine ending 'e'
  if (clean.endsWith('e') && clean.length > 3) {
    const masc = window.stripAccents(clean.slice(0, -1));
    if (window.FRENCH_VOCAB_DB[masc]) {
      const match = window.FRENCH_VOCAB_DB[masc];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en + " (fem.)",
        pos: match.pos,
        ipa: match.ipa,
        gender: "f"
      };
    }
  }

  // 7. Past participles (-é, -ée, -és, -ées -> -er)
  if (/(é|ee|es|ees|e)$/.test(noAcc) && noAcc.length > 3) {
    const ppStem = noAcc.replace(/(ees|ee|es|e)$/, '');
    const infEr = ppStem + 'er';
    if (ppStem.length >= 2 && window.FRENCH_VOCAB_DB[infEr]) {
      const match = window.FRENCH_VOCAB_DB[infEr];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en + ` [form of ${infEr}]`,
        pos: "verbe / participe",
        ipa: match.ipa || `/${clean}/`,
        gender: ""
      };
    }
  }

  // 8. Passé simple verb forms (-a -> -er; -irent -> -ir / -er)
  if (noAcc.endsWith('a') && noAcc.length > 3) {
    const inf = noAcc.slice(0, -1) + 'er';
    if (window.FRENCH_VOCAB_DB[inf]) {
      const match = window.FRENCH_VOCAB_DB[inf];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en + " [passé simple]",
        pos: "verbe",
        ipa: match.ipa || `/${clean}/`,
        gender: ""
      };
    }
  }
  if (noAcc.endsWith('irent') && noAcc.length > 5) {
    const infEr = noAcc.slice(0, -5) + 'er';
    const infIr = noAcc.slice(0, -5) + 'ir';
    const target = window.FRENCH_VOCAB_DB[infEr] ? infEr : (window.FRENCH_VOCAB_DB[infIr] ? infIr : null);
    if (target) {
      const match = window.FRENCH_VOCAB_DB[target];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en + " [they did - passé simple]",
        pos: "verbe",
        ipa: match.ipa || `/${clean}/`,
        gender: ""
      };
    }
  }

  // 9. General verb endings (imparfait, présent, futur, conditionnel)
  const verbEndings = ['assent', 'erions', 'eriez', 'erait', 'eront', 'aient', 'erent', 'ions', 'iez', 'ait', 'ais', 'ant', 'era', 'ent', 'ons', 'ez', 'er', 'ir', 're', 'ai', 'as', 'at', 'it'];
  for (const ending of verbEndings) {
    if (noAcc.endsWith(ending) && noAcc.length > ending.length + 2) {
      const stem = noAcc.slice(0, -ending.length);
      const infinitiveEr = stem + 'er';
      if (window.FRENCH_VOCAB_DB[infinitiveEr]) {
        const match = window.FRENCH_VOCAB_DB[infinitiveEr];
        return {
          word: rawWord,
          cleanWord: clean,
          en: match.en + ` [form of ${infinitiveEr}]`,
          pos: "verbe",
          ipa: match.ipa || `/${clean}/`,
          gender: ""
        };
      }
      const infinitiveIr = stem + 'ir';
      if (window.FRENCH_VOCAB_DB[infinitiveIr]) {
        const match = window.FRENCH_VOCAB_DB[infinitiveIr];
        return {
          word: rawWord,
          cleanWord: clean,
          en: match.en + ` [form of ${infinitiveIr}]`,
          pos: "verbe",
          ipa: match.ipa || `/${clean}/`,
          gender: ""
        };
      }
      if (window.FRENCH_VOCAB_DB[stem]) {
        const match = window.FRENCH_VOCAB_DB[stem];
        return {
          word: rawWord,
          cleanWord: clean,
          en: match.en,
          pos: match.pos || "mot",
          ipa: match.ipa || `/${clean}/`,
          gender: match.gender || ""
        };
      }
    }
  }

  // 10. Adverbs ending in -ment
  if (noAcc.endsWith('ment') && noAcc.length > 5) {
    const adjStem = noAcc.slice(0, -4);
    if (window.FRENCH_VOCAB_DB[adjStem]) {
      const match = window.FRENCH_VOCAB_DB[adjStem];
      return {
        word: rawWord,
        cleanWord: clean,
        en: match.en + " (adverbially)",
        pos: "adverbe",
        ipa: `/${clean}/`,
        gender: ""
      };
    }
  }

  // 11. Mark as fallback so live dictionary lookup is always triggered
  return {
    word: rawWord,
    cleanWord: clean,
    en: `Looking up "${rawTrim}"...`,
    pos: "mot",
    ipa: `/${clean}/`,
    gender: "",
    isFallback: true
  };
};

